var nodes = require("./nodes");
var flows = require("./flows");
var flow = require("./flow");
var context = require("./context");
var auth = require("../auth");
var info = require("./settings");
var plugins = require("./plugins");
var diagnostics = require("./diagnostics");

var apiUtil = require("../util");
// GEMINOS
var causeway = require("./causeway")
var typedb = require("./typedb")
var causewaydiscovery = require("./causeway-discovery")

module.exports = {
    init: function (settings, runtimeAPI) {
        flows.init(runtimeAPI);
        flow.init(runtimeAPI);
        nodes.init(runtimeAPI);
        context.init(runtimeAPI);
        info.init(settings, runtimeAPI);
        plugins.init(runtimeAPI);
        diagnostics.init(settings, runtimeAPI);
        typedb.init(runtimeAPI, settings);
        causewaydiscovery.init(runtimeAPI, settings);
        causeway.init(runtimeAPI, settings);
        const needsPermission = auth.needsPermission;
        const adminApp = apiUtil.createExpressApp(settings)

        // Flows
        adminApp.get("/flows", needsPermission("flows.read"), flows.get, apiUtil.errorHandler);
        adminApp.post("/flows", needsPermission("flows.write"), flows.post, apiUtil.errorHandler);

        // Flows/state
        adminApp.get("/flows/state", needsPermission("flows.read"), flows.getState, apiUtil.errorHandler);
        if (settings.runtimeState && settings.runtimeState.enabled === true) {
            adminApp.post("/flows/state", needsPermission("flows.write"), flows.postState, apiUtil.errorHandler);
        }

        // Flow
        adminApp.get("/flow/:id", needsPermission("flows.read"), flow.get, apiUtil.errorHandler);
        adminApp.post("/flow", needsPermission("flows.write"), flow.post, apiUtil.errorHandler);
        adminApp.delete("/flow/:id", needsPermission("flows.write"), flow.delete, apiUtil.errorHandler);
        adminApp.put("/flow/:id", needsPermission("flows.write"), flow.put, apiUtil.errorHandler);

        // Nodes
        adminApp.get("/nodes", needsPermission("nodes.read"), nodes.getAll, apiUtil.errorHandler);

        if (!settings.externalModules || !settings.externalModules.palette || settings.externalModules.palette.allowInstall !== false) {
            if (!settings.externalModules || !settings.externalModules.palette || settings.externalModules.palette.allowUpload !== false) {
                const multer = require('multer');
                const upload = multer({ storage: multer.memoryStorage() });
                adminApp.post("/nodes", needsPermission("nodes.write"), upload.single("tarball"), nodes.post, apiUtil.errorHandler);
            } else {
                adminApp.post("/nodes", needsPermission("nodes.write"), nodes.post, apiUtil.errorHandler);
            }
        }
        adminApp.get(/^\/nodes\/messages/, needsPermission("nodes.read"), nodes.getModuleCatalogs, apiUtil.errorHandler);
        adminApp.get(/^\/nodes\/((@[^\/]+\/)?[^\/]+\/[^\/]+)\/messages/, needsPermission("nodes.read"), nodes.getModuleCatalog, apiUtil.errorHandler);
        adminApp.get(/^\/nodes\/((@[^\/]+\/)?[^\/]+)$/, needsPermission("nodes.read"), nodes.getModule, apiUtil.errorHandler);
        adminApp.put(/^\/nodes\/((@[^\/]+\/)?[^\/]+)$/, needsPermission("nodes.write"), nodes.putModule, apiUtil.errorHandler);
        adminApp.delete(/^\/nodes\/((@[^\/]+\/)?[^\/]+)$/, needsPermission("nodes.write"), nodes.delete, apiUtil.errorHandler);
        adminApp.get(/^\/nodes\/((@[^\/]+\/)?[^\/]+)\/([^\/]+)$/, needsPermission("nodes.read"), nodes.getSet, apiUtil.errorHandler);
        adminApp.put(/^\/nodes\/((@[^\/]+\/)?[^\/]+)\/([^\/]+)$/, needsPermission("nodes.write"), nodes.putSet, apiUtil.errorHandler);

        // Context
        adminApp.get("/context/:scope(global)", needsPermission("context.read"), context.get, apiUtil.errorHandler);
        adminApp.get("/context/:scope(global)/*", needsPermission("context.read"), context.get, apiUtil.errorHandler);
        adminApp.get("/context/:scope(node|flow)/:id", needsPermission("context.read"), context.get, apiUtil.errorHandler);
        adminApp.get("/context/:scope(node|flow)/:id/*", needsPermission("context.read"), context.get, apiUtil.errorHandler);

        // adminApp.delete("/context/:scope(global)",needsPermission("context.write"),context.delete,apiUtil.errorHandler);
        adminApp.delete("/context/:scope(global)/*", needsPermission("context.write"), context.delete, apiUtil.errorHandler);
        // adminApp.delete("/context/:scope(node|flow)/:id",needsPermission("context.write"),context.delete,apiUtil.errorHandler);
        adminApp.delete("/context/:scope(node|flow)/:id/*", needsPermission("context.write"), context.delete, apiUtil.errorHandler);

        adminApp.get("/settings", needsPermission("settings.read"), info.runtimeSettings, apiUtil.errorHandler);

        // Plugins
        adminApp.get("/plugins", needsPermission("plugins.read"), plugins.getAll, apiUtil.errorHandler);
        adminApp.get("/plugins/messages", needsPermission("plugins.read"), plugins.getCatalogs, apiUtil.errorHandler);
        adminApp.get("/diagnostics", needsPermission("diagnostics.read"), diagnostics.getReport, apiUtil.errorHandler);

        // TypeDB
        adminApp.post("/typedb/set-host", needsPermission("typedb.write"), typedb.set_host, apiUtil.errorHandler);
        adminApp.get("/typedb/get-host", needsPermission("typedb.write"), typedb.get_host, apiUtil.errorHandler);
        adminApp.get("/typedb/get-dbs", needsPermission("typedb.write"), typedb.get_dbs, apiUtil.errorHandler);

        adminApp.post("/typedb/causewayRepo", needsPermission("typedb.write"), typedb.causewayRepo, apiUtil.errorHandler);
        adminApp.post("/typedb/deploy_instances", needsPermission("typedb.write"), typedb.deployInstances, apiUtil.errorHandler)
        adminApp.post("/typedb/knowledge", needsPermission("typedb.write"), typedb.knowledge, apiUtil.errorHandler);
        adminApp.post("/typedb/storeCausalAnalysis", needsPermission("typedb.write"), typedb.storeCausalAnalysis, apiUtil.errorHandler);


        // CAUSEWAY
        adminApp.get("/causeway/getLicense", needsPermission("causeway.read"), causeway.getLicense, apiUtil.errorHandler);
        adminApp.get("/causeway/validateLicense", needsPermission("causeway.read"), causeway.validateLicense, apiUtil.errorHandler);
        adminApp.get("/causeway/getType", needsPermission("causeway.read"), causeway.getType, apiUtil.errorHandler);
        adminApp.get("/causeway/getCausewayConfig", needsPermission("causeway.read"), causeway.getCausewayConfig, apiUtil.errorHandler);
        adminApp.get("/causeawy/getDataAverages", needsPermission("causeeway.read"), causeway.getDataAverages, apiUtil.errorHandler);


        adminApp.post("/causeway/getPyWhyInfo", needsPermission("causeway.write"), causeway.getPyWhyInfo, apiUtil.errorHandler);
        adminApp.post("/causeway/getModelAnalysis", needsPermission("causeway.write"), causeway.getModelAnalysis, apiUtil.errorHandler);
        adminApp.post("/causeway/getModelAnalysisTest", needsPermission("causeway.write"), causeway.getModelAnalysisTest, apiUtil.errorHandler);
        adminApp.post("/causeway/fetchCausalAnalysis", needsPermission("causeway.write"), causeway.fetchCausalAnalysis, apiUtil.errorHandler);
        adminApp.post("/causeway/storeLicense", needsPermission("causeway.write"), causeway.storeLicense, apiUtil.errorHandler);

        adminApp.post("/causeway/updateICC", needsPermission("causeway.write"), causeway.updateICC, apiUtil.errorHandler);
        adminApp.post("/causeway/clearICC", needsPermission("causeway.write"), causeway.clearICC, apiUtil.errorHandler);
        adminApp.post("/causeway/updateCausalMechanism", needsPermission("causeway.write"), causeway.updateCausalMechanism, apiUtil.errorHandler);
        
        
        adminApp.post("/causeway/updateContext", needsPermission("causeway.write"), causeway.updateContext, apiUtil.errorHandler);
        adminApp.get("/causeway/getContext", needsPermission("causeway.write"), causeway.getContext, apiUtil.errorHandler);

        adminApp.get("/causeway/queryLinkColor", needsPermission("causeway.write"), causeway.queryLinkColor, apiUtil.errorHandler);

        // CAUSEWAY DISCOVERY
        adminApp.get("/causewaydiscovery/getPromptInfo", needsPermission("causewaydiscovery.read"), causewaydiscovery.getPromptInfo, apiUtil.errorHandler);
        adminApp.get("/causewaydiscovery/fetchGptResponse", needsPermission("causewaydiscovery.read"), causewaydiscovery.fetchGptResponse, apiUtil.errorHandler);
        adminApp.get("/causewaydiscovery/getOpenAIModels", needsPermission("causewaydiscovery.read"), causewaydiscovery.getOpenAIModels, apiUtil.errorHandler);
        adminApp.get("/causewaydiscovery/getBasicQuery", needsPermission("causeawydiscovery.read"), causewaydiscovery.getBasicQuery, apiUtil.errorHandler);
        adminApp.get("/causewaydiscovery/testGlobalContextQuery", needsPermission("causeawydiscovery.read"), causewaydiscovery.testGlobalContextQuery, apiUtil.errorHandler);
        adminApp.get("/causewaydiscovery/updateQuery", needsPermission("causeawydiscovery.read"), causewaydiscovery.updateQuery, apiUtil.errorHandler);

        // adminApp.get("/causewaydiscovery/kgCausalDiscovery", needsPermission("causewaydiscovery.read"), causewaydiscovery.fetchKgCausalDiscovery, apiUtil.errorHandler)

        adminApp.post("/causewaydiscovery/addNewRelations", needsPermission("causewaydiscovery.write"), causewaydiscovery.addNewRelations, apiUtil.errorHandler);
        adminApp.post("/causewaydiscovery/storeGptPromptInfo", needsPermission("causewaydiscovery.write"), causewaydiscovery.storeGptPromptInfo, apiUtil.errorHandler)
        adminApp.post("/causewaydiscovery/loadPrompt", needsPermission("causewaydiscovery.write"), causewaydiscovery.loadPrompt, apiUtil.errorHandler);
        adminApp.post("/causewaydiscovery/storeApiKey", needsPermission("causewaydiscovery.write"), causewaydiscovery.storeApiKey, apiUtil.errorHandler);
        adminApp.post("/causewaydiscovery/queryFlowise", needsPermission("causewaydiscovery.write"), causewaydiscovery.queryFlowise, apiUtil.errorHandler);
        adminApp.post("/causewaydiscovery/queryLlamaIndex", needsPermission("causewaydiscovery.write"), causewaydiscovery.queryLlamaIndex, apiUtil.errorHandler);

        return adminApp;
    }
}
